"""LAN replay/session analysis UI."""
from __future__ import annotations


def session_library_page_html():
    return r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Race Engineer Sessions</title><link rel="icon" href="data:image/svg+xml;base64,"><style>
:root{--bg:#080d12;--panel:#101720;--panel2:#0c131a;--line:#263746;--text:#eaf1f6;--muted:#8ea0af;--cyan:#4ed5ff;--amber:#f5be4f;--green:#31df94;--red:#ff5b6e;--purple:#b585ff}
*{box-sizing:border-box}body{font-family:Segoe UI,system-ui;background:var(--bg);color:var(--text);margin:0;padding:clamp(10px,1.25vw,20px);font-size:14px}.top{display:flex;align-items:center;gap:10px;margin-bottom:12px;position:sticky;top:0;z-index:5;background:rgba(8,13,18,.97);padding:6px 0}.top h1{margin:0;flex:1;font-size:clamp(23px,2vw,34px)}button,input,select{background:#111a23;color:var(--text);border:1px solid var(--line);border-radius:7px;padding:8px 10px}button{cursor:pointer}button:hover{border-color:#50758e}.danger{border-color:#71313b;color:#ff9aa4}.toolbar,.compare,.transport,.lapbar,.cornerbar,.eventbar{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.shell{display:grid;grid-template-columns:minmax(280px,360px) minmax(0,1fr);gap:12px}.sidebar,.panel,.card{background:var(--panel);border:1px solid var(--line);border-radius:10px}.sidebar{padding:10px;max-height:calc(100vh - 110px);overflow:auto}.row{background:#111821;border:1px solid #2a3946;border-radius:9px;padding:11px;margin:8px 0;cursor:pointer}.row.sel{border-color:var(--cyan);background:#13232d}.row>b{font-size:15px}.meta,.sub{color:var(--muted);font-size:12px}.tag{display:inline-block;background:#243141;padding:2px 6px;border-radius:7px;margin:4px 4px 0 0}.detail{min-width:0}.panel{padding:12px;margin-bottom:10px}.headrow{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap}.headrow h2,.headrow h3{margin:0}.workhead{display:grid;grid-template-columns:minmax(250px,.8fr) minmax(0,1.7fr);gap:10px}.mapcard{min-width:0}.mapbox{height:300px;background:#080f15;border:1px solid #1d2b37;border-radius:9px;position:relative;overflow:hidden}.mapbox canvas{width:100%;height:100%;display:block}.charts{display:grid;grid-template-columns:1fr;gap:9px}.chartCard{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:9px}.chartHead{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:5px}.chartTitle{font-size:15px;font-weight:800}.chartSub{color:var(--muted);font-size:11px}.chartCard canvas{width:100%;height:160px;display:block;background:#091017;border-radius:7px}.legend{display:flex;gap:12px;color:var(--muted);font-size:11px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:4px}.statuspill{border:1px solid var(--line);border-radius:999px;padding:5px 9px;color:var(--muted);font-size:11px}.statuspill.live{color:var(--green);border-color:#236648}.currentCorner{font-size:18px;font-weight:900;color:var(--cyan)}.timeline{max-height:180px;overflow:auto}.event{padding:5px;border-bottom:1px solid #202d38;cursor:pointer}.event:hover{background:#15222c}.cornerbar button.active{border-color:var(--cyan);color:var(--cyan)}.transport button.primary{background:#173040;border-color:#3b718d}.sectionTitle{font-size:12px;color:var(--cyan);font-weight:900;letter-spacing:.08em;margin-bottom:6px}.hidden{display:none!important}.compareResult canvas{width:100%;height:120px;background:#0d1014;margin:6px 0}.empty{padding:25px;color:var(--muted);text-align:center}.channelGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.advanced{margin-top:9px}.advanced summary{cursor:pointer;color:var(--cyan);font-weight:800;margin-bottom:8px}
@media(max-width:1200px){.shell{grid-template-columns:1fr}.sidebar{max-height:320px}.workhead{grid-template-columns:1fr}.mapbox{height:260px}}@media(max-width:850px){.channelGrid{grid-template-columns:1fr}.transport{align-items:stretch}.transport select,.transport button{flex:1 1 auto}}@media(max-width:600px){body{padding:8px}.top{flex-wrap:wrap}.top h1{flex-basis:100%}.mapbox{height:220px}}
</style></head><body>
<div class=top><button onclick=goBack()>BACK</button><h1>Replay / Session Analysis</h1><button onclick=load()>REFRESH</button></div>
<div class=toolbar><input id=q placeholder="Search sessions"><label><input type=checkbox id=fav> Favorites</label><button onclick=load()>Search</button></div>
<div class=compare><select id=left></select><select id=right></select><button onclick=compareSessions()>Compare sessions</button></div>
<div class=shell><div class=sidebar id=rows>Loading…</div><div class=detail id=detail><div class="panel empty">Select a session.</div></div></div>
<script>
function goBack(){location.href='/performance'}
let sessions=[],current=null,details=null,selected=new Set(),ws=null,wsLap=null,wsRef=null,cursorDistance=null,zoomRange=null,selectedCorner=null,eventIndex=-1,replayPoll=null;
const channels=[['speed_kph','Speed','km/h'],['brake','Brake','%'],['throttle','Throttle','%'],['steer','Steering','input'],['gear','Gear',''],['ers_percent','ERS','%'],['delta_s','Delta','s'],['rpm','RPM','rpm'],['g_lateral','Lat G','g'],['g_longitudinal','Long G','g']];
async function jget(u){let r=await fetch(u);return await r.json()}
async function jpost(u,d){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});return await r.json()}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtTime(v){return Number.isFinite(Number(v))?Number(v).toFixed(3):'--'}
async function load(){let q=encodeURIComponent(document.getElementById('q').value),fav=document.getElementById('fav').checked?'1':'0',d=await jget('/api/sessions?q='+q+'&favorite='+fav);sessions=d.sessions||[];let root=document.getElementById('rows');root.innerHTML='';for(let s of sessions){let e=document.createElement('div');e.className='row'+(current===s.file?' sel':'');e.onclick=()=>openSession(s.file,e);let sess=s.session||{};e.innerHTML=`<b>${esc(s.name)}</b>${s.favorite?' ★':''}<div class=meta>${esc(s.file)} · ${(s.size/1048576).toFixed(1)} MB · ${s.packet_count||'?'} packets · ${s.laps?.length||0} laps</div><div>${(s.tags||[]).map(x=>`<span class=tag>${esc(x)}</span>`).join('')}</div><div class=meta>Track ID ${sess.track_id??'?'} · Session ${sess.session_type??'?'} · UID ${s.session_uid??'?'}</div><div style="margin-top:7px"><button class=danger onclick="event.stopPropagation();deleteRecording('${esc(s.file)}')">DELETE RECORDING</button></div>`;root.appendChild(e)}if(!sessions.length)root.textContent='No recordings found.';for(let id of ['left','right']){let el=document.getElementById(id);el.innerHTML=sessions.map(s=>`<option value="${esc(s.file)}">${esc(s.name)}</option>`).join('')}}
async function deleteRecording(file){if(!file)return;if(!confirm(`Delete recorded session ${file}?\n\nThis permanently deletes the .areplay recording and replay cache. Performance Hub history is kept.`))return;let d=await jpost('/api/sessions',{action:'delete',file});if(!d.ok){alert('Delete failed: '+(d.error||'unknown error'));return}if(current===file){current=null;details=null;ws=null;document.getElementById('detail').innerHTML='<div class="panel empty">Select a session.</div>'}await load()}
async function openSession(file,el){document.querySelectorAll('.row').forEach(x=>x.classList.remove('sel'));el?.classList.add('sel');current=file;details=await jget('/api/replay/details?file='+encodeURIComponent(file));let laps=(details.laps||[]).filter(x=>x.trace_samples>1),best=details.best_trace_lap||details.best_lap||(laps[0]||{}).lap;wsLap=best;wsRef=best;selected.clear();renderSessionShell();if(best)await loadWorkstation();startReplayPoll()}
function renderSessionShell(){let d=details||{},laps=(d.laps||[]).filter(x=>x.trace_samples>1),corners=d.corners||[],assoc=d.associations||{};document.getElementById('detail').innerHTML=`
<div class=panel><div class=headrow><div><h2>${esc(current)}</h2><div class=meta>Best lap L${d.best_lap??'?'} · best trace L${d.best_trace_lap??'?'} · ${d.packet_count||0} packets</div></div><button class=danger onclick="deleteRecording('${esc(current)}')">DELETE RECORDING</button></div></div>
<div class=panel><div class=sectionTitle>REPLAY-LINKED TELEMETRY WORKSTATION</div><div class=lapbar><label>Lap <select id=wsLap>${laps.map(l=>`<option value="${l.lap}" ${l.lap==wsLap?'selected':''}>L${l.lap} · ${fmtTime(l.lap_time_s)}</option>`).join('')}</select></label><label>Reference <select id=wsRef>${laps.map(l=>`<option value="${l.lap}" ${l.lap==wsRef?'selected':''}>L${l.lap} · ${fmtTime(l.lap_time_s)}</option>`).join('')}</select></label><button onclick=loadWorkstation()>LOAD COMPARISON</button><span id=replayState class=statuspill>Replay controls unavailable</span></div>
<div class=transport style="margin-top:9px"><button onclick="replayControl('load',{lap:wsLap})">LOAD REPLAY</button><button class=primary onclick="replayControl('toggle')" id=playPause>PLAY / PAUSE</button><label>Speed <select id=replaySpeed onchange="replayControl('speed',{speed:+this.value})"><option>.5</option><option selected>1</option><option>2</option><option>4</option><option>8</option></select>x</label><button onclick=stepEvent(-1)>◀ EVENT</button><button onclick=stepEvent(1)>EVENT ▶</button><button onclick=resetZoom()>FULL LAP</button></div></div>
<div id=workstation class=hidden></div>
<div class=panel><div class=sectionTitle>LEGACY SESSION TOOLS</div><div class=lapbar>${(d.laps||[]).map(l=>`<button onclick="toggleLap(${l.lap})" data-lap="${l.lap}">L${l.lap} ${l.lap_time_s?l.lap_time_s.toFixed(3):''}</button>`).join('')}</div><button onclick=compareLaps()>Compare selected laps</button><h3>Corner jump</h3><div class=cornerbar>${corners.map(c=>`<button onclick="jump(${c.packet})">L${c.lap} ${esc(c.label)}</button>`).join('')||'No CORNER COACH trace associated.'}</div><h3>Associated files</h3><div class=meta>Report: ${esc(assoc.coach_report_json||'none')}<br>Validation: ${esc(assoc.validation_json||'none')}<br>Corner traces: ${(assoc.corner_validation||[]).length}</div><h3>Coaching timeline</h3><div class=timeline>${(d.timeline||[]).map((e,i)=>`<div class=event onclick="jump(${e.packet})"><b>${esc(e.event)}</b> L${e.lap??'-'} ${e.label?esc(e.label):''} ${e.text?'— '+esc(e.text):''}</div>`).join('')||'No timeline.'}</div><div id=compare class=compareResult></div></div>`;
document.getElementById('wsLap')?.addEventListener('change',async e=>{wsLap=+e.target.value;selectedCorner=null;zoomRange=null;await loadWorkstation()});document.getElementById('wsRef')?.addEventListener('change',async e=>{wsRef=+e.target.value;await loadWorkstation()})}
async function loadWorkstation(){if(!current||!wsLap)return;let d=await jpost('/api/replay/workstation',{file:current,lap:wsLap,reference_lap:wsRef});if(!d.ok){document.getElementById('workstation').className='panel';document.getElementById('workstation').innerHTML='<div class=empty>'+esc(d.error||'Workstation unavailable')+'</div>';return}ws=d.result;cursorDistance=null;zoomRange=null;selectedCorner=null;eventIndex=-1;renderWorkstation()}
function renderWorkstation(){let root=document.getElementById('workstation');root.className='';let lm=ws.lap_meta||{},rm=ws.reference_meta||{};root.innerHTML=`<div class=workhead><div class="panel mapcard"><div class=headrow><div><div class=sectionTitle>LINKED MAP</div><div class=currentCorner id=currentCorner>FULL LAP</div><div class=meta>L${ws.lap} ${fmtTime(lm.lap_time_s)} vs L${ws.reference_lap} ${fmtTime(rm.lap_time_s)}</div></div><span class=statuspill id=cursorText>Move over any graph</span></div><div class=mapbox><canvas id=wsMap></canvas></div><div class=cornerbar id=cornerButtons style="margin-top:8px"></div><div class=eventbar id=phaseJumps style="margin-top:8px"></div></div><div class=panel><div class=sectionTitle>SHARED DISTANCE CURSOR</div><div class=meta>Move across any chart to synchronize all channels and the map. Click a chart to seek the active replay.</div><div class=legend style="margin-top:7px"><span><i class=dot style="background:var(--amber)"></i>Driver L${ws.lap}</span><span><i class=dot style="background:var(--cyan)"></i>Reference L${ws.reference_lap}</span></div><div class=channelGrid id=primaryCharts></div><details class=advanced open><summary>MORE TELEMETRY</summary><div class=channelGrid id=advancedCharts></div></details></div></div>`;
let primary=['speed_kph','brake','throttle','steer','gear','delta_s'],advanced=['ers_percent','rpm','g_lateral','g_longitudinal'];for(let [key,title,unit] of channels){let host=(primary.includes(key)?document.getElementById('primaryCharts'):document.getElementById('advancedCharts'));if(!host)continue;let card=document.createElement('div');card.className='chartCard';card.innerHTML=`<div class=chartHead><div><div class=chartTitle>${title}</div><div class=chartSub>${unit}</div></div><span class=meta id="val_${key}">--</span></div><canvas id="chart_${key}" data-key="${key}"></canvas>`;host.appendChild(card)}
let cb=document.getElementById('cornerButtons');cb.innerHTML=(ws.corners||[]).map(c=>`<button data-corner="${c.corner_id}" onclick="selectWorkCorner(${c.corner_id})">${esc(c.label)}</button>`).join('')||'<span class=meta>No corner markers in replay evidence.</span>';wireCharts();drawAll();drawMap()}
function visibleRange(){let d=ws?.distance_m||[];if(!d.length)return [0,1];return zoomRange||[d[0],d[d.length-1]]}
function seriesRows(){return ws?.series||[]}
function channelValue(row,key,i){let v=(row?.[key]||[])[i];if(key==='brake'||key==='throttle')return Number.isFinite(+v)?+v*100:v;if(key==='steer')return Number.isFinite(+v)?+v*100:v;return v}
function drawChart(canvas,key){let ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect(),W=Math.max(500,Math.round(rect.width*devicePixelRatio)),H=Math.round(160*devicePixelRatio);canvas.width=W;canvas.height=H;ctx.clearRect(0,0,W,H);let grid=ws.distance_m||[],rows=seriesRows(),[xmin,xmax]=visibleRange(),indices=grid.map((d,i)=>[d,i]).filter(x=>x[0]>=xmin&&x[0]<=xmax);let vals=[];for(let r of rows)for(let [,i] of indices){let v=channelValue(r,key,i);if(Number.isFinite(+v))vals.push(+v)}if(!vals.length){ctx.fillStyle='#7e909f';ctx.font=`${12*devicePixelRatio}px Segoe UI`;ctx.fillText('N/A',12*devicePixelRatio,25*devicePixelRatio);return}let mn=Math.min(...vals),mx=Math.max(...vals);if(mx-mn<.001){mn-=1;mx+=1}let pad=24*devicePixelRatio,x=d=>pad+(d-xmin)*(W-2*pad)/Math.max(.001,xmax-xmin),y=v=>pad+(mx-v)*(H-2*pad)/(mx-mn);ctx.strokeStyle='#22313e';ctx.lineWidth=devicePixelRatio;for(let j=0;j<5;j++){let yy=pad+j*(H-2*pad)/4;ctx.beginPath();ctx.moveTo(pad,yy);ctx.lineTo(W-pad,yy);ctx.stroke()}let colors=['#f5be4f','#4ed5ff'];rows.slice(0,2).forEach((r,ri)=>{ctx.strokeStyle=colors[ri];ctx.lineWidth=2*devicePixelRatio;ctx.setLineDash(ri?[6*devicePixelRatio,4*devicePixelRatio]:[]);ctx.beginPath();let started=false;for(let [d,i] of indices){let v=channelValue(r,key,i);if(!Number.isFinite(+v))continue;let xx=x(d),yy=y(+v);if(!started){ctx.moveTo(xx,yy);started=true}else ctx.lineTo(xx,yy)}ctx.stroke();ctx.setLineDash([])});if(cursorDistance!=null&&cursorDistance>=xmin&&cursorDistance<=xmax){ctx.strokeStyle='#fff';ctx.lineWidth=devicePixelRatio;let xx=x(cursorDistance);ctx.beginPath();ctx.moveTo(xx,pad);ctx.lineTo(xx,H-pad);ctx.stroke()}}
function wireCharts(){document.querySelectorAll('.chartCard canvas').forEach(c=>{c.addEventListener('pointermove',e=>{let r=c.getBoundingClientRect(),[xmin,xmax]=visibleRange(),d=xmin+Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*(xmax-xmin);setCursor(d)});c.addEventListener('click',async e=>{let r=c.getBoundingClientRect(),[xmin,xmax]=visibleRange(),d=xmin+Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*(xmax-xmin);setCursor(d);await seekDistance(d)})})}
function setCursor(d){cursorDistance=d;let sample=nearestSample(d),corner=nearestCorner(d);document.getElementById('cursorText').textContent=`${Math.round(d)} m${sample?' · '+sample.speed_kph+' km/h':''}`;document.getElementById('currentCorner').textContent=corner?corner.label:'FULL LAP';for(let [key] of channels){let el=document.getElementById('val_'+key);if(!el)continue;let row=seriesRows()[0],grid=ws.distance_m||[],i=nearestIndex(grid,d),v=channelValue(row,key,i);el.textContent=Number.isFinite(+v)?(+v).toFixed(key==='gear'||key==='rpm'?0:2):'--'}drawAll();drawMap()}
function nearestIndex(a,v){let bi=0,bd=Infinity;a.forEach((x,i)=>{let d=Math.abs(+x-v);if(d<bd){bd=d;bi=i}});return bi}
function nearestSample(d){let a=ws?.samples||[],best=null,bd=Infinity;for(let s of a){let x=+s.distance_m;if(!Number.isFinite(x))continue;let dd=Math.abs(x-d);if(dd<bd){bd=dd;best=s}}return best}
function nearestCorner(d){let a=ws?.corners||[],best=null,bd=Infinity;for(let c of a){let dd=Math.abs(+c.distance_m-d);if(dd<bd){bd=dd;best=c}}return bd<180?best:null}
function drawAll(){document.querySelectorAll('.chartCard canvas').forEach(c=>drawChart(c,c.dataset.key))}
function drawMap(){let c=document.getElementById('wsMap');if(!c||!ws)return;let ctx=c.getContext('2d'),r=c.getBoundingClientRect(),W=Math.max(400,Math.round(r.width*devicePixelRatio)),H=Math.max(220,Math.round(r.height*devicePixelRatio));c.width=W;c.height=H;ctx.clearRect(0,0,W,H);let pts=(ws.samples||[]).filter(s=>Number.isFinite(+s.x)&&Number.isFinite(+s.z));if(pts.length<2){ctx.fillStyle='#8294a3';ctx.fillText('No world-position trace',15,25);return}let xs=pts.map(p=>+p.x),zs=pts.map(p=>+p.z),mnx=Math.min(...xs),mxx=Math.max(...xs),mnz=Math.min(...zs),mxz=Math.max(...zs),pad=25*devicePixelRatio,scale=Math.min((W-2*pad)/Math.max(1,mxx-mnx),(H-2*pad)/Math.max(1,mxz-mnz)),px=p=>pad+(+p.x-mnx)*scale,py=p=>H-pad-(+p.z-mnz)*scale;ctx.strokeStyle='#6f8190';ctx.lineWidth=5*devicePixelRatio;ctx.lineJoin='round';ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(px(p),py(p)):ctx.moveTo(px(p),py(p)));ctx.stroke();for(let co of ws.corners||[]){let s=nearestSample(co.distance_m);if(!s)continue;ctx.fillStyle=selectedCorner===co.corner_id?'#4ed5ff':'#f0f4f7';ctx.beginPath();ctx.arc(px(s),py(s),6*devicePixelRatio,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dce5eb';ctx.font=`${10*devicePixelRatio}px Segoe UI`;ctx.fillText(co.label,px(s)+8*devicePixelRatio,py(s)-7*devicePixelRatio)}if(cursorDistance!=null){let s=nearestSample(cursorDistance);if(s){ctx.fillStyle='#f5be4f';ctx.beginPath();ctx.arc(px(s),py(s),7*devicePixelRatio,0,Math.PI*2);ctx.fill()}}c.onclick=async e=>{let rr=c.getBoundingClientRect(),mx=(e.clientX-rr.left)*devicePixelRatio,my=(e.clientY-rr.top)*devicePixelRatio,best=null,bd=Infinity;for(let p of pts){let dd=Math.hypot(px(p)-mx,py(p)-my);if(dd<bd){bd=dd;best=p}}if(best){let d=+best.distance_m;cursorDistance=d;zoomRange=[Math.max(0,d-220),d+280];drawAll();drawMap();await seekDistance(d)}}}
function selectWorkCorner(cid){selectedCorner=cid;let c=(ws.corners||[]).find(x=>+x.corner_id===+cid);if(!c)return;cursorDistance=+c.distance_m;zoomRange=[Math.max(0,+c.distance_m-260),+c.distance_m+260];document.querySelectorAll('#cornerButtons button').forEach(b=>b.classList.toggle('active',+b.dataset.corner===+cid));document.getElementById('currentCorner').textContent=c.label;let pj=document.getElementById('phaseJumps');pj.innerHTML=`<button ${c.brake_packet==null?'disabled':''} onclick="jump(${c.brake_packet})">BRAKE POINT</button><button ${c.apex_packet==null?'disabled':''} onclick="jump(${c.apex_packet})">APEX</button><button ${c.throttle_packet==null?'disabled':''} onclick="jump(${c.throttle_packet})">THROTTLE PICKUP</button>`;drawAll();drawMap()}
function resetZoom(){zoomRange=null;selectedCorner=null;document.querySelectorAll('#cornerButtons button').forEach(b=>b.classList.remove('active'));drawAll();drawMap()}
async function seekDistance(d){let s=nearestSample(d);if(s?.packet!=null)await replayControl('seek',{packet:s.packet})}
async function replayControl(action,extra={}){if(!current)return;let d=await jpost('/api/replay/control',{action,file:current,...extra});if(!d.ok){let el=document.getElementById('replayState');if(el)el.textContent=d.error||'Replay control unavailable';return}renderReplayStatus(d.status)}
function syncCursorToReplayStatus(s){if(!ws||!Array.isArray(ws.samples)||!ws.samples.length||s?.position==null)return;let pos=+s.position;if(!Number.isFinite(pos))return;let best=null,bd=Infinity;for(let sample of ws.samples){let p=+sample.packet;if(!Number.isFinite(p))continue;let dd=Math.abs(p-pos);if(dd<bd){bd=dd;best=sample}}if(best&&Number.isFinite(+best.distance_m)){let d=+best.distance_m;if(cursorDistance==null||Math.abs(cursorDistance-d)>.5){cursorDistance=d;setCursor(d)}}}
function renderReplayStatus(s){if(!s)return;let el=document.getElementById('replayState');if(el){el.classList.toggle('live',!!s.active&&!s.paused);el.textContent=`${s.active===false?'LIVE MODE · ':''}${s.paused?'PAUSED':'PLAYING'} · x${Number(s.speed||1).toFixed(2)} · ${s.position||0}/${Math.max(0,(s.total||1)-1)}${s.rebuilding?' · SEEKING':''}`}let pp=document.getElementById('playPause');if(pp)pp.textContent=s.paused?'PLAY':'PAUSE';let sp=document.getElementById('replaySpeed');if(sp&&[...sp.options].some(o=>+o.value===+s.speed))sp.value=String(s.speed);if(s.active&&!s.rebuilding)syncCursorToReplayStatus(s)}
function startReplayPoll(){if(replayPoll)clearInterval(replayPoll);replayPoll=setInterval(async()=>{if(!current)return;try{let d=await jget('/api/replay/status');if(d.available)renderReplayStatus(d)}catch(e){}},250)}
async function stepEvent(dir){let ev=(ws?.events||[]).filter(e=>e.packet!=null);if(!ev.length)return;let status=await jget('/api/replay/status'),pos=+status.position||0;if(dir>0){eventIndex=ev.findIndex(e=>+e.packet>pos);if(eventIndex<0)eventIndex=0}else{for(let i=ev.length-1;i>=0;i--)if(+ev[i].packet<pos){eventIndex=i;break}if(eventIndex<0)eventIndex=ev.length-1}await jump(ev[eventIndex].packet)}
function toggleLap(n){if(selected.has(n))selected.delete(n);else selected.add(n);document.querySelectorAll('[data-lap]').forEach(b=>b.style.outline=selected.has(+b.dataset.lap)?'2px solid #fff':'none')}
function drawLegacy(canvas,grid,series,key){let c=canvas.getContext('2d'),w=canvas.width=900,h=canvas.height=130;c.clearRect(0,0,w,h);let vals=series.flatMap(s=>(s[key]||[]).filter(v=>v!=null));if(!vals.length)return;let mn=Math.min(...vals),mx=Math.max(...vals);if(mx==mn)mx=mn+1;series.forEach((s,si)=>{c.beginPath();(s[key]||[]).forEach((v,i)=>{if(v==null)return;let x=i/Math.max(1,grid.length-1)*w,y=h-(v-mn)/(mx-mn)*h;i?c.lineTo(x,y):c.moveTo(x,y)});c.strokeStyle=['#fff','#5fd','#fa6','#f8f'][si%4];c.stroke()});c.fillStyle='#aaa';c.fillText(key,6,12)}
function renderCompare(d){let root=document.getElementById('compare');let series=d.series||[d.left,d.right].filter(Boolean),grid=d.distance_m||[];root.innerHTML=['speed_kph','brake','throttle','gear','ers_percent','delta_s'].map(k=>`<canvas data-k="${k}"></canvas>`).join('');root.querySelectorAll('canvas').forEach(c=>drawLegacy(c,grid,series,c.dataset.k))}
async function compareLaps(){if(!current||selected.size<2)return;let d=await jpost('/api/replay/compare-laps',{file:current,laps:[...selected]});renderCompare(d.result||d)}
async function compareSessions(){let d=await jpost('/api/replay/compare-sessions',{left:document.getElementById('left').value,right:document.getElementById('right').value});let r=d.result||d;document.getElementById('detail').innerHTML=`<div class=panel><h2>Session comparison</h2><div>Best-lap delta: ${r.best_lap_delta_s??'n/a'} s</div><div id=compare class=compareResult></div></div>`;renderCompare(r)}
async function jump(packet){if(packet==null)return;let d=await jpost('/api/replay/jump',{file:current,packet});if(!d.ok)alert(d.error||'Jump unavailable')}
load();
</script></body></html>'''
